pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Create a dummy target that will revert on any call
        address dummy = address(0xdead);
        address from = address(this);
        address[] memory tos = new address[](1);
        tos[0] = dummy;
        // The reference contract will make a call to dummy (which reverts), so transfer reverts
        // The buggy contract (loop starts at 1) will not make any call because _tos.length == 1, so transfer succeeds
        bool ok;
        try c.transfer(from, dummy, tos, 100) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference C reverts => ok == false; buggy M does not revert => ok == true
        assertTrue(!ok, "Expected revert for reference contract");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a helper contract that records calls to transferFrom
        // We'll use a simple counter contract
        // Since we can only interact via c, we'll deploy a separate contract for tracking calls
        // But we must observe c's behavior through public surface - we can check if the buggy contract
        // fails to make the first call by checking a revert/no-revert scenario.
        // Instead, use a simple approach: deploy a contract that reverts on first call and not on second.
        // But simpler: we know the difference is that the buggy contract skips the first element.
        // We'll use an array with two addresses where the first address is a contract that will revert
        // on transferFrom AND the second is a normal address. The reference will revert (because it calls first), 
        // while the buggy will succeed (since it skips the first). 
        // However the problem says test must pass on reference and fail on buggy. So we assert that the call reverts.

        // Deploy a simple contract that reverts on any call
        Reverter reverter = new Reverter();

        address[] memory tos = new address[](2);
        tos[0] = address(reverter);
        tos[1] = address(0xdead);

        bool ok;
        try c.transfer(address(0xaaa), address(reverter), tos, 100) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference contract should revert because it calls the first address which reverts
        // Buggy contract skips first address so it does not revert
        assertTrue(ok == false, "Reference should revert");
    }
}

contract Reverter {
    fallback() external payable {
        revert("always revert");
    }
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("always revert");
    }
}
